import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class ClientsScreen extends ConsumerStatefulWidget {    const ClientsScreen({super.key})      @override    ConsumerState<ClientsScreen> createState() => _ClientsScreenState()  }    class _ClientsScreenState extends ConsumerState<ClientsScreen> {    List<dynamic> _clients = []    bool _isLoading = true    final _searchController = TextEditingController()      @override    void initState() {      super.initState()      _loadClients()    }      Future<void> _loadClients() async {      try {        final clients = await ApiClient().getClients()        if (mounted) setState(() { _clients = clients; _isLoading = false })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      List<dynamic> get _filteredClients {      if (_searchController.text.isEmpty) return _clients      final query = _searchController.text.toLowerCase()      return _clients.where((c) {        final name = (c['name'] ?? '').toString().toLowerCase()        final email = (c['email'] ?? '').toString().toLowerCase()        final company = (c['company'] ?? '').toString().toLowerCase()        return name.contains(query) || email.contains(query) || company.contains(query)      }).toList()    }      Future<void> _showAddClientDialog() async {      final nameController = TextEditingController()      final emailController = TextEditingController()      final phoneController = TextEditingController()      final companyController = TextEditingController()      final innController = TextEditingController()        await showModalBottomSheet(        context: context,        isScrollControlled: true,        shape: const RoundedRectangleBorder(          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),        ),        builder: (context) => Padding(          padding: EdgeInsets.only(            bottom: MediaQuery.of(context).viewInsets.bottom,            left: 20,            right: 20,            top: 20,          ),          child: Column(            mainAxisSize: MainAxisSize.min,            crossAxisAlignment: CrossAxisAlignment.stretch,            children: [              Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  const Text('Новый клиент', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),                  IconButton(                    icon: const Icon(Icons.close),                    onPressed: () => Navigator.pop(context),                  ),                ],              ),              const SizedBox(height: 16),              TextField(                controller: nameController,                decoration: InputDecoration(                  labelText: 'Имя *',                  prefixIcon: const Icon(Icons.person_outline),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: emailController,                keyboardType: TextInputType.emailAddress,                decoration: InputDecoration(                  labelText: 'Email',                  prefixIcon: const Icon(Icons.email_outline),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: phoneController,                keyboardType: TextInputType.phone,                decoration: InputDecoration(                  labelText: 'Телефон',                  prefixIcon: const Icon(Icons.phone_outline),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: companyController,                decoration: InputDecoration(                  labelText: 'Компания',                  prefixIcon: const Icon(Icons.business_outlined),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: innController,                decoration: InputDecoration(                  labelText: 'ИНН',                  prefixIcon: const Icon(Icons.numbers),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 20),              ElevatedButton(                onPressed: () async {                  if (nameController.text.isEmpty) return                  try {                    await ApiClient().createClient({                      'name': nameController.text,                      'email': emailController.text,                      'phone': phoneController.text,                      'company': companyController.text,                      'inn': innController.text,                    })                    if (mounted) {                      Navigator.pop(context)                      _loadClients()                      ScaffoldMessenger.of(context).showSnackBar(                        const SnackBar(content: Text('Клиент добавлен')),                      )                    }                  } catch (e) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Ошибка: $e')),                    )                  }                },                style: ElevatedButton.styleFrom(                  padding: const EdgeInsets.symmetric(vertical: 16),                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                ),                child: const Text('Сохранить', style: TextStyle(fontSize: 16)),              ),              const SizedBox(height: 20),            ],          ),        ),      )    }      @override    Widget build(BuildContext context) {      return Scaffold(        appBar: AppBar(          title: const Text('Клиенты'),          actions: [            IconButton(              icon: const Icon(Icons.add),              onPressed: _showAddClientDialog,            ),          ],        ),        body: Column(          children: [            // Search            Padding(              padding: const EdgeInsets.all(16),              child: TextField(                controller: _searchController,                onChanged: (_) => setState(() {}),                decoration: InputDecoration(                  hintText: 'Поиск клиентов...',                  prefixIcon: const Icon(Icons.search),                  suffixIcon: _searchController.text.isNotEmpty                      ? IconButton(                          icon: const Icon(Icons.clear),                          onPressed: () {                            _searchController.clear()                            setState(() {})                          },                        )                      : null,                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                  contentPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),                ),              ),            ),              // List            Expanded(              child: _isLoading                  ? const LoadingWidget()                  : _filteredClients.isEmpty                      ? const EmptyState(                          icon: Icons.people_outline,                          title: 'Нет клиентов',                          subtitle: 'Добавьте первого клиента',                        )                      : RefreshIndicator(                          onRefresh: _loadClients,                          child: ListView.builder(                            padding: const EdgeInsets.symmetric(horizontal: 16),                            itemCount: _filteredClients.length,                            itemBuilder: (context, index) {                              final client = _filteredClients[index]                              return Card(                                margin: const EdgeInsets.only(bottom: 12),                                child: ListTile(                                  leading: CircleAvatar(                                    backgroundColor: Theme.of(context).colorScheme.primary.withOpacity(0.1),                                    child: Text(                                      (client['name'] ?? 'U').toString()[0].toUpperCase(),                                      style: TextStyle(                                        color: Theme.of(context).colorScheme.primary,                                        fontWeight: FontWeight.bold,                                      ),                                    ),                                  ),                                  title: Text(                                    client['name'] ?? 'Без имени',                                    style: const TextStyle(fontWeight: FontWeight.w600),                                  ),                                  subtitle: Column(                                    crossAxisAlignment: CrossAxisAlignment.start,                                    children: [                                      if (client['email'] != null)                                        Text(client['email'], style: TextStyle(fontSize: 12, color: Colors.grey[600])),                                      if (client['phone'] != null)                                        Text(client['phone'], style: TextStyle(fontSize: 12, color: Colors.grey[600])),                                      if (client['company'] != null)                                        Text(client['company'], style: TextStyle(fontSize: 12, color: Colors.grey[600])),                                    ],                                  ),                                  trailing: Container(                                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),                                    decoration: BoxDecoration(                                      color: (client['status'] == 'active' ? Colors.green : Colors.grey).withOpacity(0.1),                                      borderRadius: BorderRadius.circular(8),                                    ),                                    child: Text(                                      client['status'] == 'active' ? 'Активен' : 'Неактивен',                                      style: TextStyle(                                        fontSize: 10,                                        color: client['status'] == 'active' ? Colors.green[700] : Colors.grey[600],                                      ),                                    ),                                  ),                                ),                              )                            },                          ),                        ),            ),          ],        ),      )    }  }